//! HTTP API for mex-scrape (axum), with an OpenAPI spec generated by utoipa.
//!
//! The spec is the contract with the Next.js app in `web/`: its TypeScript
//! client is generated from it (`npm --prefix web run gen:api`).

use axum::{Json, Router, routing::get};
use serde::Serialize;
use utoipa::{OpenApi, ToSchema};
use utoipa_axum::{router::OpenApiRouter, routes};

/// Path where the OpenAPI spec is served.
pub const OPENAPI_PATH: &str = "/api-docs/openapi.json";

#[derive(OpenApi)]
#[openapi(info(
    title = "mex-scrape API",
    version = "0.1.0",
    description = "Backend API for mex-scrape."
))]
struct ApiDoc;

/// Liveness response for `GET /health`.
#[derive(Debug, Serialize, ToSchema)]
pub struct HealthResponse {
    /// Always `"ok"` when the process is serving requests.
    pub status: String,
}

/// Report that the API process is alive (does not check the database).
#[utoipa::path(
    get,
    path = "/health",
    operation_id = "health",
    responses((status = OK, description = "API is alive", body = HealthResponse))
)]
async fn health() -> Json<HealthResponse> {
    Json(HealthResponse {
        status: "ok".to_owned(),
    })
}

/// Builds the application router and its OpenAPI spec.
///
/// The returned router also serves the spec at [`OPENAPI_PATH`].
pub fn router() -> (Router, utoipa::openapi::OpenApi) {
    let (router, api) = OpenApiRouter::with_openapi(ApiDoc::openapi())
        .routes(routes!(health))
        .split_for_parts();
    let spec = api.clone();
    let router = router.route(
        OPENAPI_PATH,
        get(move || {
            let spec = spec.clone();
            async move { Json(spec) }
        }),
    );
    (router, api)
}

/// Returns the OpenAPI spec without building a server.
pub fn openapi() -> utoipa::openapi::OpenApi {
    router().1
}
